const unlinkSocketPath = async (socketPath: string): Promise<void> => {
  try {
    await fs.unlink(socketPath)
  } catch (error: any) {
    handleArgsSocketCatchError(error)
  }
}

const listen = (server: http.Server, { host, port, socket, "socket-mode": socketMode }: ListenOptions) => {
  return new Promise<void>(async (resolve, reject) => {
    server.on("error", reject)

    const onListen = async () => {
      try {
        if (socket && typeof socketMode !== "undefined" && process.platform !== "win32") {
          await fs.chmod(socket, socketMode)
        }

        // Promise resolved earlier so this is an unrelated error.
        server.off("error", reject)
        server.on("error", (err) => util.logError(logger, "http server error", err))

        resolve()
      } catch (error) {
        server.close(() => reject(error))
      }
    }

    if (socket) {
      await unlinkSocketPath(socket)
      server.listen(socket, () => void onListen())
    } else {
      // [] is the correct format when using :: but Node errors with them.
      server.listen(port, host.replace(/^\[|\]$/g, ""), () => void onListen())
    }
  })
}

