export function splitOnFirstEquals(str: string): string[] {
  // we use regex instead of "=" to ensure we split at the first
  // "=" and return the following substring with it
  // important for the hashed-password which looks like this
  // $argon2i$v=19$m=4096,t=3,p=1$0qR/o+0t00hsbJFQCKSfdQ$oFcM4rL6o+B7oxpuA4qlXubypbBPsf+8L531U7P9HYY
  // 2 means return two items
  // Source: https://stackoverflow.com/a/4607799/3015595
  // We use the ? to say the the substr after the = is optional
  const split = str.split(/=(.+)?/, 2)

  return split
}

const socketModeRegex = /^[0-7]{3,4}$/

const validateSocketMode = (mode: string): void => {
  if (!socketModeRegex.test(mode)) {
    throw new Error("--socket-mode must be a valid octal file mode")
  }
}

const parseSocketOption = (
  value: string,
): Pick<UserProvidedArgs, "socket" | "socket-mode" | "socket-owner" | "socket-group"> => {
  const parts = value.split(",")
  if (parts.length > 4 || parts[0] === "") {
    throw new Error("--socket must be in the format path[,mode[,owner[,group]]]")
  }

  const [socketPath, socketMode, socketOwner, socketGroup] = parts
  const socketArgs: Pick<UserProvidedArgs, "socket" | "socket-mode" | "socket-owner" | "socket-group"> = {
    socket: path.resolve(socketPath),
  }

  if (socketMode) {
    validateSocketMode(socketMode)
    socketArgs["socket-mode"] = socketMode
  }

  if (socketOwner) {
    socketArgs["socket-owner"] = socketOwner
  }

  if (socketGroup) {
    socketArgs["socket-group"] = socketGroup
  }

  return socketArgs
}

/**
 * Parse arguments into UserProvidedArgs.  This should not go beyond checking
 * that arguments are valid types and have values when required.
 */
export const parse = (
  argv: string[],
  opts?: {
    configFile?: string
  },
): UserProvidedArgs => {
  const error = (msg: string): Error => {
    if (opts?.configFile) {
      msg = `error reading ${opts.configFile}: ${msg}`
    }

    return new Error(msg)
  }

  const args: UserProvidedArgs = {}
  let ended = false

  for (let i = 0; i < argv.length; ++i) {
    const arg = argv[i]

    // -- signals the end of option parsing.
    if (!ended && arg === "--") {
      ended = true
      continue
    }

    // Options start with a dash and require a value if non-boolean.
    if (!ended && arg.startsWith("-")) {
      let key: keyof UserProvidedArgs | undefined
      let value: string | undefined
      if (arg.startsWith("--")) {
        const split = splitOnFirstEquals(arg.replace(/^--/, ""))
        key = split[0] as keyof UserProvidedArgs
        value = split[1]
      } else {
        const short = arg.replace(/^-/, "")
        const pair = Object.entries(options).find(([, v]) => v.short === short)
        if (pair) {
          key = pair[0] as keyof UserProvidedArgs
        }
      }

      if (!key || !options[key]) {
        throw error(`Unknown option ${arg}`)
