import { logger } from "@coder/logger"
import * as cp from "child_process"
import compression from "compression"
import express, { Express } from "express"
import { promises as fs } from "fs"
import http from "http"
import * as httpolyglot from "httpolyglot"
import { promisify } from "util"
import { Disposable } from "../common/emitter"
import * as util from "../common/util"
import { DefaultedArgs } from "./cli"
import { disposer } from "./http"
import { isNodeJSErrnoException } from "./util"
import { handleUpgrade } from "./wsRouter"

type ListenOptions = Pick<DefaultedArgs, "socket" | "port" | "host" | "socket-mode" | "socket-owner" | "socket-group">

const execFile = promisify(cp.execFile)

const parseSocketMode = (mode: string): number => parseInt(mode, 8)

const tryResolveName = async (command: string, args: string[], regex: RegExp): Promise<number | undefined> => {
  try {
    const { stdout } = await execFile(command, args)
    const match = stdout.match(regex)
    if (match) {
      return parseInt(match[1], 10)
    }
  } catch (error) {
    if (isNodeJSErrnoException(error) && error.code === "ENOENT") {
      return undefined
    }

    return undefined
  }

  return undefined
}

const resolveSocketUid = async (owner: string): Promise<number> => {
  if (/^\d+$/.test(owner)) {
    return parseInt(owner, 10)
  }

  const uid = await tryResolveName("id", ["-u", owner], /^\s*(\d+)\s*$/m)
  if (typeof uid !== "undefined") {
    return uid
  }

  throw new Error(`Could not resolve socket owner "${owner}"`)
}

const resolveSocketGid = async (group: string): Promise<number> => {
  if (/^\d+$/.test(group)) {
    return parseInt(group, 10)
  }

  const gid = await tryResolveName("getent", ["group", group], /^[^:]*:[^:]*:(\d+):/m)
  if (typeof gid !== "undefined") {
    return gid
  }

  const dscacheutilGid = await tryResolveName("dscacheutil", ["-q", "group", "-a", "name", group], /gid:\s*(\d+)/m)
  if (typeof dscacheutilGid !== "undefined") {
    return dscacheutilGid
  }

  const dsclGid = await tryResolveName("dscl", [".", "-read", `/Groups/${group}`, "PrimaryGroupID"], /PrimaryGroupID:\s*(\d+)/m)
  if (typeof dsclGid !== "undefined") {
    return dsclGid
  }

  throw new Error(`Could not resolve socket group "${group}"`)
}

const setSocketMetadata = async (socketPath: string, args: ListenOptions): Promise<void> => {
  if (args["socket-mode"]) {
    await fs.chmod(socketPath, parseSocketMode(args["socket-mode"]))
  }

  if (args["socket-owner"] || args["socket-group"]) {
    const stat = await fs.stat(socketPath)
    const uid = args["socket-owner"] ? await resolveSocketUid(args["socket-owner"]) : stat.uid
    const gid = args["socket-group"] ? await resolveSocketGid(args["socket-group"]) : stat.gid
    await fs.chown(socketPath, uid, gid)
  }
}

export interface App extends Disposable {
  /** Handles regular HTTP requests. */
  router: Express
  /** Handles websocket requests. */
  wsRouter: Express
  /** The underlying HTTP server. */
  server: http.Server
}

const listen = (server: http.Server, args: ListenOptions) => {
  const { host, port, socket } = args
  return new Promise<void>(async (resolve, reject) => {
    server.on("error", reject)

    const onListen = async () => {
      // Promise resolved earlier so this is an unrelated error.
      server.off("error", reject)
      server.on("error", (err) => util.logError(logger, "http server error", err))

      try {
        if (socket) {
          await setSocketMetadata(socket, args)
        }
        resolve()
      } catch (error) {
        server.close(() => reject(error))
      }
    }

    if (socket) {
      try {
        await fs.unlink(socket)
      } catch (error: any) {
        handleArgsSocketCatchError(error)
      }

      server.listen(socket, onListen)
    } else {
      // [] is the correct format when using :: but Node errors with them.
      server.listen(port, host.replace(/^\[|\]$/g, ""), onListen)
    }
  })
}

